function manualCoordinates(data){const latitude=String(data.latitude??'').trim(),longitude=String(data.longitude??'').trim();if(!latitude&&!longitude)return null;if(!latitude||!longitude)throw new Error('Ingresa tanto latitud como longitud, o deja ambos campos vacíos.');const parsedLatitude=Number(latitude),parsedLongitude=Number(longitude);if(!Number.isFinite(parsedLatitude)||parsedLatitude<-90||parsedLatitude>90||!Number.isFinite(parsedLongitude)||parsedLongitude<-180||parsedLongitude>180)throw new Error('Las coordenadas manuales no tienen un formato válido.');return{latitude:parsedLatitude,longitude:parsedLongitude}}
async function resolveCoordinates(address){await loadAdminMaps();return new Promise((resolve,reject)=>new google.maps.Geocoder().geocode({address:`${address}, Perú`},(results,status)=>{if(status==='OK'&&results[0])return resolve({latitude:results[0].geometry.location.lat(),longitude:results[0].geometry.location.lng()});const messages={ZERO_RESULTS:'Google Maps no encontró esta dirección. Revísala e intenta nuevamente.',REQUEST_DENIED:'Google rechazó la consulta. Habilita Geocoding API y revisa las restricciones de la clave.',OVER_QUERY_LIMIT:'Se alcanzó el límite de consultas de Google Maps. Intenta nuevamente más tarde.',INVALID_REQUEST:'Google recibió una dirección inválida.'};reject(new Error(messages[status]||`No se pudieron obtener coordenadas (${status}).`))}))}
async function loadAttentionPointsAdmin(){const points=await fetch('/api/attention-points').then(r=>r.json());attentionPointContainer.innerHTML=points.length?points.map(point=>`<div class="admin-row"><div><strong>${escapeHtml(point.name)}</strong><small>${escapeHtml(point.address)} · ${point.latitude!==null&&point.longitude!==null?'Coordenadas guardadas':'Coordenadas pendientes'}</small></div><div><button class="text-button edit-attention-point" data-id="${point.id}">Editar</button><button class="text-button delete-attention-point" data-id="${point.id}">Eliminar</button></div></div>`).join(''):'<p>Aún no hay puntos registrados.</p>';geocodeAttentionPointsButton.disabled=!points.some(point=>point.latitude===null||point.longitude===null);document.querySelectorAll('.edit-attention-point').forEach(button=>button.addEventListener('click',()=>editAttentionPoint(points.find(point=>point.id===Number(button.dataset.id)))));document.querySelectorAll('.delete-attention-point').forEach(button=>button.addEventListener('click',async()=>{if(confirm('¿Eliminar este punto de recojo?')){await fetch(`/api/attention-points/${button.dataset.id}`,{method:'DELETE'});if(attentionPointBeingEdited===Number(button.dataset.id))resetAttentionPointForm();loadAttentionPointsAdmin()}}));return points}
attentionPointForm.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(attentionPointForm)),editing=Boolean(attentionPointBeingEdited);let suppliedCoordinates;try{suppliedCoordinates=manualCoordinates(data)}catch(error){attentionPointMessage.textContent=error.message;return}attentionPointMessage.textContent='Guardando ubicación…';try{const coordinates=suppliedCoordinates||await resolveCoordinates(data.address);Object.assign(data,coordinates);const response=await fetch(editing?`/api/attention-points/${attentionPointBeingEdited}`:'/api/attention-points',{method:editing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudo guardar el punto.');resetAttentionPointForm();await loadAttentionPointsAdmin();attentionPointMessage.textContent=editing?'Punto y coordenadas actualizados.':'Punto y coordenadas guardados.'}catch(error){const response=await fetch(editing?`/api/attention-points/${attentionPointBeingEdited}`:'/api/attention-points',{method:editing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();attentionPointMessage.textContent=response.ok?`Punto guardado, pero las coordenadas siguen pendientes: ${error.message}`:(result.message||error.message)}});
geocodeAttentionPointsButton.addEventListener('click',async()=>{const points=(await fetch('/api/attention-points').then(r=>r.json())).filter(point=>point.latitude===null||point.longitude===null);geocodeAttentionPointsButton.disabled=true;attentionPointMessage.textContent=`Actualizando ${points.length} ubicación(es)…`;let completed=0;try{for(const point of points){const coordinates=await resolveCoordinates(point.address);await fetch(`/api/attention-points/${point.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({...point,...coordinates})});completed++}await loadAttentionPointsAdmin();attentionPointMessage.textContent=`Coordenadas guardadas para ${completed} ubicación(es).`}catch(error){attentionPointMessage.textContent=`Se actualizaron ${completed} ubicación(es). ${error.message}`;geocodeAttentionPointsButton.disabled=false}});loadAttentionPointsAdmin();
